# A chemical network for Honghu.jl (https://github.com/chongchonghe/Honghu.jl),
# generated by JAFF from its `honghu` template. Do not edit this file: change the
# network or its .jfunc and generate it again.
#
# The network is a module holding one type, named after the network's label and a
# subtype of `Honghu.AbstractNetwork`; the file binds that type to the same name in the
# module it is included in.
# Honghu supplies everything that is the same for every network (unpacking the state,
# the temperature, the tolerance scales); this file supplies the rest. The constant
# properties are methods of the type, which Honghu forwards from an instance.
#
# The state of one cell, in the order of JAFF's `rhses` with radiation order 0:
#
#     u = [n_1 ... n_NS, E, photden_1, rflux_1, ..., photden_NB, rflux_NB]
#
# with `n` the species number densities (cm^-3), `E` the internal energy density
# (erg cm^-3), `photden` the photon number density of a band divided by
# `phi = c_hat / c` and `rflux` the factor by which absorption has attenuated the
# band's flux. It needs radiation bands, `mode = "nph"` and `rsl = "c_hat"` under
# `[network.radiation]`, as in the jaffgen.toml shipped with this template (a `--config`
# of your own replaces it, so repeat them there). Honghu passes the reduced speed of
# light as `c_hat`, and the label must be a valid Julia name other than `Network`.
$$JAFF DEFINE honghu {
    REPLACE {
        "nden\[\s*(\d+)\s*\]" -> "nden[\1+1]"         # JAFF indexes from zero
        "photden\[\s*(\d+)\s*\]" -> "photden[\1+1]"
        "rflux\[\s*(\d+)\s*\]" -> "rflux[\1+1]"
    }
    THERMAL { MODE -> dedt  ENERGY -> volumetric }
    RADIATION { ENABLED -> True }
}

$$JAFF SUB label
module JAFF_$label$
$$JAFF END

import ..Honghu

$$JAFF SUB label, nspec, nbands
const NSPEC = $nspec$
const NBANDS = $nbands$

struct $label${T<:AbstractFloat} <: Honghu.AbstractNetwork
    options::Honghu.NetworkOptions{NBANDS,T}
end

# The name the methods below are written against, whatever the label.
const Network = $label$
$$JAFF END

Network(; kwargs...) = Network(Honghu.NetworkOptions{NBANDS}(; kwargs...))

Honghu.nspecies(::Type{<:Network}) = NSPEC
Honghu.nbands(::Type{<:Network}) = NBANDS

$$JAFF REPEAT specie IN species
Honghu.species_names(::Type{<:Network}) = tuple("$specie$", )
$$JAFF END

$$JAFF REPEAT specie_mass IN specie_masses
Honghu.species_masses(::Type{<:Network}) = tuple($specie_mass$, )
$$JAFF END

$$JAFF REPEAT reaction IN reactions
Honghu.network_reactions(::Type{<:Network}) = tuple("$reaction$", )
$$JAFF END

$$JAFF REPEAT radiation_boundary IN radiation_boundaries { REPLACE { "\boo\b" -> "Inf" } }
Honghu.band_edges(::Type{<:Network}) = tuple($radiation_boundary$, )
$$JAFF END

function Honghu.jaff_rhs!(du, ::Network, nden, photden, rflux, tgas, c_hat)
    $$JAFF REPEAT idx, rhs, cse IN rhses { USE honghu }
    cse$idx$ = $cse$
    du[$idx+1$] = $rhs$
    $$JAFF END
    return nothing
end

function Honghu.jaff_jacobian!(J, ::Network, nden, photden, rflux, tgas, c_hat)
    $$JAFF REPEAT idx, expr, cse IN jacobian { USE honghu }
    cse$idx$ = $cse$
    J[$idx+1$, $idx+1$] = $expr$
    $$JAFF END
    return nothing
end

end # module

$$JAFF SUB label, nspec, nbands
const $label$ = JAFF_$label$.$label$

@doc """
    $label$(; photon_energy, groups, isothermal = nothing, Tmin = 1.0)

The chemical network `$label$`, generated by JAFF with its `honghu` template
($nspec$ species, $nbands$ radiation band(s)). The keywords are those of
[`NetworkOptions`](@ref); `photon_energy` is the mean photon energy of each band, in erg.

Species, in the order of the state vector: $(join(Honghu.species_names($label$), ", ")).

Reactions:
$(join(("  - `" * r * "`" for r in Honghu.network_reactions($label$)), "\n"))

Band edges, in eV: $(join(Honghu.band_edges($label$), ", ")).
""" $label$
$$JAFF END
